contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(address(this).balance >= amount, "insufficient funds");
        uint potBefore = c.pot();
        uint balBefore = address(c).balance;

        if (amount == 10) {
            c.play{value: amount}();
            uint potAfter = c.pot();
            uint balAfter = address(c).balance;
            if (potAfter == 0) {
                // win: C pays out fee (1) and pot (potBefore+10-1), both to this contract
                assert(balAfter + potBefore + 10 == balBefore);
            } else {
                // loss: pot grows by exactly 10 and C gains the ticket
                assert(potAfter == potBefore + 10);
                assert(balAfter == balBefore + 10);
            }
        } else {
            bool reverted;
            try c.play{value: amount}() { reverted = false; } catch { reverted = true; }
            assert(reverted);
            assert(c.pot() == potBefore);
            assert(address(c).balance == balBefore);
        }
    }

    receive() external payable {}
}

